package pe.edu.pucp.oceanlink;
import java.sql.*;import java.io.*;import java.util.*;

public final class ReporteContenido {
 public static void preparar(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS reporte_contenido (id_reporte BIGINT UNSIGNED PRIMARY KEY, contenido LONGBLOB NOT NULL, FOREIGN KEY(id_reporte) REFERENCES reporte_generado(id_reporte)) ENGINE=InnoDB");}}
 public static void guardar(Connection c,long id,List<String> columnas,List<String[]> filas)throws SQLException,IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(columnas.size());for(String col:columnas)out.writeUTF(col);out.writeInt(filas.size());for(String[] fila:filas)for(String value:fila){byte[] text=Objects.toString(value,"").getBytes(java.nio.charset.StandardCharsets.UTF_8);out.writeInt(text.length);out.write(text);}}try(PreparedStatement ps=c.prepareStatement("INSERT INTO reporte_contenido VALUES(?,?)")){ps.setLong(1,id);ps.setBytes(2,bytes.toByteArray());ps.executeUpdate();}}
 public static boolean cargar(jakarta.servlet.http.HttpServletRequest r,long id)throws SQLException,IOException{try(Connection c=Conexion.abrir()){try(PreparedStatement ps=c.prepareStatement("SELECT contenido FROM reporte_contenido WHERE id_reporte=?")){ps.setLong(1,id);try(ResultSet rs=ps.executeQuery()){if(!rs.next())return false;try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(rs.getBytes(1)))){int n=in.readInt();if(n<1||n>100)throw new IOException("Reporte inválido");List<String> cols=new ArrayList<>();for(int i=0;i<n;i++)cols.add(in.readUTF());int count=in.readInt();if(count<0||count>1000000)throw new IOException("Reporte inválido");List<String[]> rows=new ArrayList<>();for(int i=0;i<count;i++){String[] row=new String[n];for(int k=0;k<n;k++){int len=in.readInt();if(len<0||len>10000000)throw new IOException("Reporte inválido");row[k]=new String(in.readNBytes(len),java.nio.charset.StandardCharsets.UTF_8);}rows.add(row);}r.setAttribute("columnas",cols);r.setAttribute("filas",rows);return true;}}}}catch(SQLSyntaxErrorException ex){if(ex.getErrorCode()==1146)return false;throw ex;}}
}
